BEGIN;
CREATE EXTENSION IF NOT EXISTS pgcrypto;
CREATE SCHEMA IF NOT EXISTS universe;
REVOKE ALL ON SCHEMA universe FROM PUBLIC;
DO $$ BEGIN IF NOT EXISTS(SELECT 1 FROM pg_roles WHERE rolname='universe_api') THEN CREATE ROLE universe_api NOLOGIN NOSUPERUSER NOBYPASSRLS; END IF; END $$;
CREATE TABLE universe.tenants(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),name text NOT NULL,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE universe.credentials(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES universe.tenants(id),subject_id uuid NOT NULL,kind text NOT NULL CHECK(kind IN('operator','agent','host')),token_hash text UNIQUE NOT NULL CHECK(length(token_hash)=64),scopes text[] NOT NULL,expires_at timestamptz NOT NULL,revoked_at timestamptz,created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE universe.agents(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES universe.tenants(id),name text NOT NULL,type text NOT NULL,capabilities text[] NOT NULL DEFAULT '{}',status text NOT NULL DEFAULT 'registered',last_seen timestamptz,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,name));
CREATE TABLE universe.hosts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES universe.tenants(id),name text NOT NULL,host_type text NOT NULL DEFAULT 'persistent-linux-host',status text NOT NULL DEFAULT 'registered',capabilities text[] NOT NULL DEFAULT '{}',last_seen timestamptz,worker_version text,metadata jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,name));
CREATE TABLE universe.projects(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES universe.tenants(id),name text NOT NULL,owner uuid NOT NULL,repository text,runtime text NOT NULL DEFAULT 'docker',configuration jsonb NOT NULL DEFAULT '{}',artifact_location text,created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,name));
CREATE TABLE universe.artifacts(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES universe.tenants(id),project_id uuid NOT NULL,filename text NOT NULL,storage_path text NOT NULL UNIQUE,checksum text NOT NULL CHECK(checksum ~ '^[a-f0-9]{64}$'),size bigint NOT NULL CHECK(size>0 AND size<=104857600),version text NOT NULL,verified boolean NOT NULL DEFAULT false,created_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,project_id) REFERENCES universe.projects(tenant_id,id));
CREATE TABLE universe.tasks(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES universe.tenants(id),created_by uuid NOT NULL,assigned_to uuid NOT NULL,type text NOT NULL CHECK(type IN('deploy','update','restart','stop','start','remove','rollback','logs','status','healthcheck','build','docker-build','docker-run','docker-compose','environment-update','artifact-download','artifact-upload','system-info')),status text NOT NULL CHECK(status IN('queued','claimed','running','awaiting_approval','completed','failed','cancelled','retrying')),priority integer NOT NULL DEFAULT 0 CHECK(priority BETWEEN 0 AND 100),payload jsonb NOT NULL,result jsonb,error text,idempotency_key text NOT NULL,request_hash text NOT NULL,lease_token uuid,lease_expires_at timestamptz,attempt integer NOT NULL DEFAULT 0,created_at timestamptz NOT NULL DEFAULT now(),started_at timestamptz,completed_at timestamptz,updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),UNIQUE(tenant_id,created_by,idempotency_key),FOREIGN KEY(tenant_id,assigned_to) REFERENCES universe.hosts(tenant_id,id));
CREATE INDEX claim_ready ON universe.tasks(tenant_id,assigned_to,priority DESC,created_at) WHERE status IN('queued','retrying','claimed','running');
CREATE TABLE universe.deployments(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),tenant_id uuid NOT NULL REFERENCES universe.tenants(id),task_id uuid NOT NULL UNIQUE,project_id uuid NOT NULL,host_id uuid NOT NULL,version text NOT NULL,status text NOT NULL DEFAULT 'pending',container_ids jsonb NOT NULL DEFAULT '[]',ports jsonb NOT NULL DEFAULT '[]',domains jsonb NOT NULL DEFAULT '[]',health_status text NOT NULL DEFAULT 'unknown',logs jsonb NOT NULL DEFAULT '[]',created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(tenant_id,id),FOREIGN KEY(tenant_id,task_id) REFERENCES universe.tasks(tenant_id,id),FOREIGN KEY(tenant_id,project_id) REFERENCES universe.projects(tenant_id,id),FOREIGN KEY(tenant_id,host_id) REFERENCES universe.hosts(tenant_id,id));
CREATE TABLE universe.events(id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,tenant_id uuid NOT NULL REFERENCES universe.tenants(id),actor_id uuid NOT NULL,type text NOT NULL,resource_id uuid,data jsonb NOT NULL DEFAULT '{}',created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION universe.prevent_event_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path='' AS $$ BEGIN RAISE EXCEPTION 'Event journal is append-only'; END $$;
CREATE TRIGGER append_only BEFORE UPDATE OR DELETE ON universe.events FOR EACH ROW EXECUTE FUNCTION universe.prevent_event_mutation();
CREATE FUNCTION universe.authenticate(digest text) RETURNS TABLE(credential_id uuid,tenant_id uuid,subject_id uuid,kind text,scopes text[]) LANGUAGE sql SECURITY DEFINER SET search_path='' AS $$ SELECT id,tenant_id,subject_id,kind,scopes FROM universe.credentials WHERE token_hash=digest AND revoked_at IS NULL AND expires_at>now() $$;
REVOKE ALL ON FUNCTION universe.authenticate(text) FROM PUBLIC;
GRANT EXECUTE ON FUNCTION universe.authenticate(text) TO universe_api;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['agents','hosts','projects','artifacts','tasks','deployments','events'] LOOP EXECUTE format('ALTER TABLE universe.%I ENABLE ROW LEVEL SECURITY',t);EXECUTE format('ALTER TABLE universe.%I FORCE ROW LEVEL SECURITY',t);EXECUTE format('CREATE POLICY tenant_isolation ON universe.%I TO universe_api USING(tenant_id=nullif(current_setting(''universe.tenant_id'',true),'''')::uuid) WITH CHECK(tenant_id=nullif(current_setting(''universe.tenant_id'',true),'''')::uuid)',t); END LOOP;END $$;
GRANT USAGE ON SCHEMA universe TO universe_api;
GRANT SELECT,INSERT,UPDATE ON universe.agents,universe.hosts,universe.projects,universe.artifacts,universe.tasks,universe.deployments TO universe_api;
GRANT SELECT,INSERT ON universe.events TO universe_api;
GRANT USAGE ON ALL SEQUENCES IN SCHEMA universe TO universe_api;
CREATE TABLE universe.migrations(version text PRIMARY KEY,applied_at timestamptz NOT NULL DEFAULT now());
INSERT INTO universe.migrations(version) VALUES('001_foundation');
COMMIT;
